  "day1": ["Catedrala Mitropolitană", "Parcul Rozelor", "Muzeul de Artă"],
  "day2": ["Bastionul Theresia", "Grădina Zoologică Timișoara"],
  "day3": ["Piața Victoriei", "Muzeul de Artă", "Grădina Zoologică Timișoara"]
}

